def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--input", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--audit", type=Path, required=True)
    args = parser.parse_args()

    players = json.loads(args.input.read_text(encoding="utf-8"))
    by_name = {player["name"]: player for player in players}
    missing = sorted(set(MANUAL_RATINGS) - set(by_name))
    if missing:
        raise SystemExit("Manual override names missing from input: " + ", ".join(missing))

    audit_rows = []
    for name, values in MANUAL_RATINGS.items():
        if len(values) != len(RATING_FIELDS):
            raise SystemExit(f"{name}: expected {len(RATING_FIELDS)} ratings")
        player = by_name[name]
        for field, new_value in zip(RATING_FIELDS, values):
            old_value = player[field]
            if old_value != new_value:
                audit_rows.append({
                    "name": name, "field": field,
                    "old_rating": old_value, "new_rating": new_value,
                    "change": new_value - old_value,
                })
                player[field] = new_value

    args.output.write_text(json.dumps(players, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    with args.audit.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=["name", "field", "old_rating", "new_rating", "change"])
        writer.writeheader()
        writer.writerows(audit_rows)
    print(json.dumps({"reviewed_players": len(MANUAL_RATINGS), "rating_changes": len(audit_rows)}, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
